import ast
from pathlib import Path
files=[Path('dissect/regf/hive_format.py'),Path('dissect/regf/structure.py'),Path('dissect/regf/recovery.py'),Path('examples/recover_hive.py'),Path('tests/test_recovery.py'),Path('tests/_data/recovery/build_fixtures.py')]
for p in files:
    tree=ast.parse(p.read_text())
    imported=[]
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            for a in n.names: imported.append((a.asname or a.name.split('.')[0],n.lineno))
        elif isinstance(n,ast.ImportFrom):
            for a in n.names:
                if a.name!='*': imported.append((a.asname or a.name,n.lineno))
    names={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)}
    # also attribute bases
    for n in ast.walk(tree):
        if isinstance(n,ast.Attribute):
            cur=n
            while isinstance(cur,ast.Attribute): cur=cur.value
            if isinstance(cur,ast.Name): names.add(cur.id)
    unused=[(name,line) for name,line in imported if name not
